Q('Easy', 'Count Even Numbers', 'Count the even numbers. | Input: N, then N integers. | Output: the count.', lambda s: sum(1 for x in arrs(s) if x % 2 == 0), [L(5, '1 2 3 4 6')], LA)
Q('Easy', 'Second Element', 'Print the second element, or NONE if the list has fewer than two elements. | Input: N, then N integers. | Output: the element.', lambda s: arrs(s)[1] if len(arrs(s)) > 1 else 'NONE', [L(3, '7 8 9')], LA)
Q('Easy', 'Search a Value', 'Print the index of K in the list or -1. | Input: N, the list, then K. | Output: the index.', lambda s: (lambda t: t[1:1 + t[0]].index(t[-1]) if t[-1] in t[1:1 + t[0]] else -1)(iv(s)), [L(4, '4 8 6 2', 6)], arq(0, 9, 1, 8, 0, 9))
Q('Easy', 'Average of List', 'Print the average with two decimals. | Input: N, then N integers. | Output: the average.', lambda s: '%.2f' % (sum(arrs(s)) / len(arrs(s))), [L(3, '1 2 4')], LA)
Q('Medium', 'Second Largest', 'Print the second largest distinct value, or NONE. | Input: N, then N integers. | Output: the value.', lambda s: sorted(set(arrs(s)))[-2] if len(set(arrs(s))) > 1 else 'NONE', [L(5, '4 9 9 2 7')], ar(0, 5, 1, 8))
Q('Medium', 'Remove Duplicates', 'Print the list keeping the first copy of each value. | Input: N, then N integers. | Output: the distinct values.', lambda s: J(list(dict.fromkeys(arrs(s)))), [L(6, '1 2 1 3 2 4')], ar(0, 5, 1, 12))
Q('Medium', 'Rotate Left by K', 'Rotate the list left by K positions. | Input: N, the list, then K. | Output: the rotated list.', lambda s: (lambda t: (lambda a, k: J(a[k % len(a):] + a[:k % len(a)]))(t[1:1 + t[0]], t[-1]))(iv(s)), [L(5, '1 2 3 4 5', 2)], arq(-9, 9, 1, 8, 0, 12))
Q('Medium', 'Merge and Sort', 'Merge two lists and print the sorted result. | Input: two lines, each "N values". | Output: sorted merged list.', lambda s: J(sorted(sum((list(map(int, l.split()))[1:] for l in W(s)), []))), [L('3 3 1 2', '2 9 0')], lambda r: L(*[J([k] + [r.randint(0, 9) for _ in range(k)]) for k in (r.randint(1, 5), r.randint(1, 5))]))
Q('Medium', 'Even and Odd Split', 'Print the even numbers on line 1 and the odd numbers on line 2 (a line may be empty). | Input: N, then N integers. | Output: two lines.', lambda s: J(x for x in arrs(s) if x % 2 == 0) + '\n' + J(x for x in arrs(s) if x % 2), [L(5, '1 2 3 4 5')], LA)
Q('Medium', 'Frequency of K', 'Count how many times K appears. | Input: N, the list, then K. | Output: the count.', lambda s: (lambda t: t[1:1 + t[0]].count(t[-1]))(iv(s)), [L(5, '1 2 1 3 1', 1)], arq(0, 4, 1, 10, 0, 4))
Q('Medium', 'Running Total', 'Print the running (cumulative) sums. | Input: N, then N integers. | Output: N sums.', lambda s: J(itertools.accumulate(arrs(s))), [L(4, '1 2 3 4')], LA)
Q('Hard', 'Bubble Sort Swaps', 'Count the swaps bubble sort makes to sort the list ascending. | Input: N, then N integers. | Output: the swaps.', lambda s: (lambda a: sum(1 for i in range(len(a)) for j in range(i + 1, len(a)) if a[i] > a[j]))(arrs(s)), [L(4, '3 2 1 4')], LA)
Q('Hard', 'Pairs With Sum', 'Count pairs i<j with a[i]+a[j]=K. | Input: N, the list, then K. | Output: the count.', lambda s: (lambda t: sum(1 for i in range(t[0]) for j in range(i + 1, t[0]) if t[1 + i] + t[1 + j] == t[-1]))(iv(s)), [L(5, '1 5 7 -1 5', 6)], arq(-3, 8, 1, 10, 0, 10))
def lir(s):
    a = arrs(s); best = cur = 1
    for i in range(1, len(a)):
        cur = cur + 1 if a[i] > a[i - 1] else 1; best = max(best, cur)
    return best
Q('Hard', 'Longest Increasing Run', 'Print the length of the longest run of strictly increasing consecutive elements. | Input: N, then N integers. | Output: the length.', lir, [L(6, '1 3 5 4 7 8')], LA)
Q('Hard', 'Matrix Row Sums', 'Print the sum of each row of an R x C matrix. | Input: R C, then R rows. | Output: R sums, one per line.', lambda s: '\n'.join(str(sum(map(int, l.split()))) for l in W(s)[1:]), [L('2 3', '1 2 3', '4 5 6')], lambda r: (lambda n, m: L('%d %d' % (n, m)) + ''.join(L(J([r.randint(-5, 9) for _ in range(m)])) for _ in range(n)))(r.randint(1, 4), r.randint(1, 4)))
