Q('Hard', 'Insert In Sorted Order', 'Insert V into the sorted list so it stays sorted, and print the list. | Input: N, the sorted list, then V. | Output: the new list.', lambda s: (lambda t: J(sorted(t[1:1 + t[0]] + [t[-1]])))(iv(s)), [L(4, '1 3 5 7', 4)], lambda r: (lambda a: L(len(a), J(a), r.randint(0, 20)))(sorted(r.randint(0, 20) for _ in range(r.randint(1, 8)))))

