Q('Medium', 'Factorial Function', 'Write fact(n) and print fact(N). | Input: N (0 to 15). | Output: N!.', lambda s: math.factorial(int(s)), [L(6)], num(0, 15))
Q('Medium', 'Is Prime Function', 'Write is_prime(n) and print True or False. | Input: N. | Output: True or False.', lambda s: str((lambda n: n > 1 and all(n % d for d in range(2, int(n ** .5) + 1)))(int(s))), [L(13)], num(1, 500))
Q('Medium', 'Default Argument', 'Write power(base, exp=2) and call it with the given base and optional exponent. | Input: a line with one or two integers. | Output: the result.', lambda s: (lambda t: t[0] ** (t[1] if len(t) > 1 else 2))(iv(s)), [L('5'), L('2 5')], lambda r: L(*(['%d' % r.randint(1, 6)] if r.random() < .5 else ['%d %d' % (r.randint(1, 6), r.randint(0, 5))])))
Q('Medium', 'Return Two Values', 'Write min_max(list) that returns both values and print "min max". | Input: N, then N integers. | Output: min max.', lambda s: '%d %d' % (min(arrs(s)), max(arrs(s))), [L(4, '3 9 1 5')], LA)
Q('Medium', 'Count Vowels Function', 'Write count_vowels(text) and print the result. | Input: a line. | Output: the count.', lambda s: sum(c in 'aeiouAEIOU' for c in s), [L('Education')], WD)
Q('Medium', 'GCD Function', 'Write gcd(a, b) using recursion or a loop and print it. | Input: A then B. | Output: the GCD.', lambda s: math.gcd(*iv(s)), [L(48, 18)], two(1, 300))
Q('Medium', 'Digit Sum Function', 'Write digit_sum(n) and print it. | Input: N. | Output: the sum of digits.', lambda s: sum(map(int, s.strip())), [L(9045)], num(0, 10**8))
Q('Medium', 'Apply Twice', 'Write twice(x) that returns x*2 + 3 applied two times (f(f(x))). Print f(f(N)). | Input: N. | Output: the result.', lambda s: (lambda n: (n * 2 + 3) * 2 + 3)(int(s)), [L(5)], num(-20, 20))
Q('Hard', 'Fibonacci Function', 'Write fib(n) with F(0)=0, F(1)=1 and print fib(N). | Input: N (0 to 25). | Output: F(N).', lambda s: (lambda f: f(f, int(s)))(lambda f, k: k if k < 2 else f(f, k - 1) + f(f, k - 2)), [L(10)], num(0, 22))
Q('Hard', 'Power Recursively', 'Write power(a, b) recursively (b>=0) and print it. | Input: A then B. | Output: A^B.', lambda s: iv(s)[0] ** iv(s)[1], [L(2, 8)], lambda r: L(r.randint(1, 6), r.randint(0, 10)))
Q('Hard', 'Variable Arguments', 'Write total(*nums) and print its value for the given numbers. | Input: N, then N integers. | Output: the sum.', lambda s: sum(arrs(s)), [L(4, '1 2 3 4')], LA)
Q('Hard', 'Count Primes in List', 'Write is_prime(n) and use it to count the primes in the list. | Input: N, then N integers. | Output: the count.', lambda s: sum(1 for n in arrs(s) if n > 1 and all(n % d for d in range(2, int(n ** .5) + 1))), [L(5, '2 4 5 9 11')], ar(0, 40, 1, 10))
Q('Hard', 'Palindrome Function', 'Write is_pal(text) and print True or False, ignoring case and spaces. | Input: a line. | Output: True or False.', lambda s: str((lambda t: t == t[::-1])(''.join(c.lower() for c in s if c != ' ' and c != '\n'))), [L('Never odd or even')], lambda r: L(' '.join(''.join(r.choice('ab') for _ in range(r.randint(1, 3))) for _ in range(r.randint(1, 3)))))
Q('Hard', 'Compose Functions', 'Define f(x)=x+2, g(x)=x*3 and print g(f(N)) + f(g(N)). | Input: N. | Output: the value.', lambda s: (lambda n: (n + 2) * 3 + (n * 3 + 2))(int(s)), [L(4)], num(-20, 20))
Q('Hard', 'Binary Representation Function', 'Write to_bin(n) recursively and print the binary form of N (0 prints 0). | Input: N. | Output: the binary string.', lambda s: bin(int(s))[2:], [L(10)], num(0, 5000))
